begin;
drop policy if exists medication_orders_staff_insert on public.medication_orders;
drop policy if exists medication_orders_staff_update on public.medication_orders;

create or replace function public.create_medication_order(p_reservation_cat_id uuid,p_name text,p_prescribed_dose text,p_dose_unit text,p_administration_method text,p_scheduled_times time[],p_start_date date,p_end_date date,p_received_quantity numeric default null,p_storage_instructions text default null,p_prescription_source text default null,p_special_instructions text default null) returns public.medication_orders language plpgsql security definer set search_path=public,pg_temp as $$
declare v_org uuid;v_stay_start date;v_stay_end date;v public.medication_orders%rowtype;begin select rc.organization_id,(r.expected_check_in_at at time zone 'Asia/Taipei')::date,(r.expected_check_out_at at time zone 'Asia/Taipei')::date into v_org,v_stay_start,v_stay_end from public.reservation_cats rc join public.reservations r on r.id=rc.reservation_id and r.organization_id=rc.organization_id where rc.id=p_reservation_cat_id;if v_org is null or not public.current_user_has_org(v_org,array['owner','manager','staff']) then raise exception 'stay cat not found';end if;if length(trim(coalesce(p_name,'')))<1 or length(trim(coalesce(p_prescribed_dose,'')))<1 or length(trim(coalesce(p_administration_method,'')))<1 then raise exception 'medication name, exact prescribed dose and method are required';end if;if coalesce(array_length(p_scheduled_times,1),0)<1 then raise exception 'at least one administration time is required';end if;if p_end_date<p_start_date or p_start_date<v_stay_start or p_end_date>v_stay_end then raise exception 'medication dates must be within boarding dates';end if;insert into public.medication_orders(organization_id,reservation_cat_id,name,prescribed_dose,dose_unit,administration_method,scheduled_times,start_date,end_date,received_quantity,remaining_quantity,storage_instructions,prescription_source,confirmation_status,special_instructions,created_by,updated_by) values(v_org,p_reservation_cat_id,trim(p_name),trim(p_prescribed_dose),nullif(trim(p_dose_unit),''),trim(p_administration_method),p_scheduled_times,p_start_date,p_end_date,p_received_quantity,p_received_quantity,nullif(trim(p_storage_instructions),''),nullif(trim(p_prescription_source),''),'requires_confirmation',nullif(trim(p_special_instructions),''),auth.uid(),auth.uid()) returning * into v;return v;end $$;
revoke all on function public.create_medication_order(uuid,text,text,text,text,time[],date,date,numeric,text,text,text) from public;grant execute on function public.create_medication_order(uuid,text,text,text,text,time[],date,date,numeric,text,text,text) to authenticated;

create or replace function public.confirm_medication_order(p_order_id uuid,p_expected_version integer) returns public.medication_orders language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.medication_orders%rowtype;v_date date;v_time time;v_scheduled timestamptz;v_cat_name text;v_record_id uuid;v_checkin timestamptz;v_checkout timestamptz;begin select * into v from public.medication_orders where id=p_order_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager']) then raise exception 'permission denied';end if;if v.version<>p_expected_version then raise exception 'order changed; reload' using errcode='40001';end if;if v.confirmation_status<>'requires_confirmation' then raise exception 'order is not awaiting confirmation';end if;update public.medication_orders set confirmation_status='confirmed',confirmed_by=auth.uid(),confirmed_at=now(),updated_by=auth.uid() where id=v.id returning * into v;select c.name,coalesce(r.actual_check_in_at,r.expected_check_in_at),r.expected_check_out_at into v_cat_name,v_checkin,v_checkout from public.reservation_cats rc join public.cats c on c.id=rc.cat_id and c.organization_id=rc.organization_id join public.reservations r on r.id=rc.reservation_id and r.organization_id=rc.organization_id where rc.id=v.reservation_cat_id;
 for v_date in select d::date from generate_series(v.start_date,v.end_date,interval '1 day') d loop foreach v_time in array v.scheduled_times loop v_scheduled=(v_date+v_time) at time zone 'Asia/Taipei';if v_scheduled>=v_checkin and v_scheduled<v_checkout then insert into public.medication_records(organization_id,medication_order_id,scheduled_at,status,idempotency_key,created_by,updated_by) values(v.organization_id,v.id,v_scheduled,'pending',gen_random_uuid(),auth.uid(),auth.uid()) on conflict(organization_id,medication_order_id,scheduled_at) do nothing;select id into v_record_id from public.medication_records where organization_id=v.organization_id and medication_order_id=v.id and scheduled_at=v_scheduled;insert into public.tasks(organization_id,reservation_cat_id,task_type,title,due_at,priority,status,source_type,source_id,idempotency_key,created_by,updated_by) values(v.organization_id,v.reservation_cat_id,'medication',coalesce(v_cat_name,'貓咪')||'｜用藥：'||v.name,v_scheduled,3,'pending','medication_record',v_record_id,'medication:'||v.id||':'||v_scheduled,auth.uid(),auth.uid()) on conflict(organization_id,idempotency_key) do nothing;end if;end loop;end loop;return v;end $$;
revoke all on function public.confirm_medication_order(uuid,integer) from public;grant execute on function public.confirm_medication_order(uuid,integer) to authenticated;

create or replace function public.claim_medication_task(p_record_id uuid,p_expected_version integer) returns public.medication_records language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.medication_records%rowtype;v_confirmed text;begin select mr.* into v from public.medication_records mr where mr.id=p_record_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'record not found';end if;select mo.confirmation_status into v_confirmed from public.medication_orders mo where mo.id=v.medication_order_id and mo.organization_id=v.organization_id;if v_confirmed<>'confirmed' then raise exception 'medication order is not confirmed';end if;if v.version<>p_expected_version then raise exception 'record changed; reload before administering' using errcode='40001';end if;if v.status<>'pending' then raise exception 'medication task is not claimable; uncertain results require manager verification';end if;update public.medication_records set status='in_progress',claimed_by=auth.uid(),claimed_at=now(),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.claim_medication_task(uuid,integer) from public;grant execute on function public.claim_medication_task(uuid,integer) to authenticated;

create or replace function public.finish_medication_task(p_record_id uuid,p_expected_version integer,p_status text,p_notes text default null) returns public.medication_records language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.medication_records%rowtype;begin select * into v from public.medication_records where id=p_record_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'record not found';end if;if v.version<>p_expected_version or v.status<>'in_progress' or v.claimed_by<>auth.uid() then raise exception 'claim lost or record changed' using errcode='40001';end if;if p_status not in('administered','unsuccessful','requires_confirmation','paused','not_applicable') then raise exception 'invalid medication status';end if;if p_status in('unsuccessful','requires_confirmation') and length(trim(coalesce(p_notes,'')))<2 then raise exception 'failure or uncertainty requires notes';end if;update public.medication_records set status=p_status,actual_administered_at=case when p_status='administered' then now() end,responsible_staff=auth.uid(),notes=nullif(trim(p_notes),''),updated_by=auth.uid() where id=v.id returning * into v;if p_status in('unsuccessful','requires_confirmation') then update public.tasks set status='requires_confirmation',updated_by=auth.uid() where organization_id=v.organization_id and source_type='medication_record' and source_id=v.id and status in('pending','in_progress');insert into public.tasks(organization_id,task_type,title,description,due_at,priority,status,source_type,source_id,idempotency_key,created_by,updated_by) values(v.organization_id,'medication_follow_up','用藥結果需人工確認',p_notes,now(),3,'requires_confirmation','medication_record',v.id,'med-follow-up:'||v.id,auth.uid(),auth.uid()) on conflict(organization_id,idempotency_key) do nothing;else update public.tasks set status='completed',completed_by=auth.uid(),completed_at=now(),updated_by=auth.uid() where organization_id=v.organization_id and source_type='medication_record' and source_id=v.id and status in('pending','in_progress');end if;return v;end $$;
revoke all on function public.finish_medication_task(uuid,integer,text,text) from public;grant execute on function public.finish_medication_task(uuid,integer,text,text) to authenticated;

create or replace function public.resolve_medication_record(p_record_id uuid,p_expected_version integer,p_resolution text,p_notes text) returns public.medication_records language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.medication_records%rowtype;begin select * into v from public.medication_records where id=p_record_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager']) then raise exception 'permission denied';end if;if v.version<>p_expected_version then raise exception 'record changed; reload' using errcode='40001';end if;if v.status not in('requires_confirmation','unsuccessful') then raise exception 'record does not require resolution';end if;if p_resolution not in('retry','close_unsuccessful','not_applicable') or length(trim(coalesce(p_notes,'')))<2 then raise exception 'resolution and notes are required';end if;update public.medication_records set status=case p_resolution when 'retry' then 'pending' when 'not_applicable' then 'not_applicable' else 'unsuccessful' end,claimed_by=null,claimed_at=null,responsible_staff=case when p_resolution='retry' then null else auth.uid() end,notes=concat_ws(E'\n',notes,'[主管確認] '||trim(p_notes)),updated_by=auth.uid() where id=v.id returning * into v;update public.tasks set status=case when p_resolution='retry' then 'pending' else 'completed' end,completed_by=case when p_resolution='retry' then null else auth.uid() end,completed_at=case when p_resolution='retry' then null else now() end,updated_by=auth.uid() where organization_id=v.organization_id and source_type='medication_record' and source_id=v.id and task_type='medication';update public.tasks set status='completed',completed_by=auth.uid(),completed_at=now(),updated_by=auth.uid() where organization_id=v.organization_id and source_type='medication_record' and source_id=v.id and task_type='medication_follow_up' and status='requires_confirmation';return v;end $$;
revoke all on function public.resolve_medication_record(uuid,integer,text,text) from public;grant execute on function public.resolve_medication_record(uuid,integer,text,text) to authenticated;
commit;
